function moonSymbol(cx,cy,r,f,waning=false){let pts=[];const sign=waning?-1:1;for(let j=0;j<=40;j++){const y=-1+j/20;pts.push(`${cx+sign*r*Math.sqrt(Math.max(0,1-y*y))},${cy+r*y}`);}for(let j=40;j>=0;j--){const y=-1+j/20;pts.push(`${cx+sign*r*(1-2*f)*Math.sqrt(Math.max(0,1-y*y))},${cy+r*y}`);}return `<circle cx="${cx}" cy="${cy}" r="${r}" fill="#263e50"/>${f?`<polygon points="${pts.join(' ')}" fill="#e8e0b6"/>`:''}`;}
function drawSpaceModel(m,d){const s=m.experiment.states[d.mode],model=m.experiment.model;let b='';const tx=(x,y,t,z=13)=>`<text x="${x}" y="${y}" font-size="${z}" fill="#244b3b">${esc(t)}</text>`,line=(x,y,a,z,c='#d5ad49',w=3)=>`<line x1="${x}" y1="${y}" x2="${a}" y2="${z}" stroke="${c}" stroke-width="${w}"/>`,sun=(x,y,r=23)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="#e2b857"/>`,earth=(x,y,r=55)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="#34576c"/><path d="M${x} ${y-r}A${r} ${r} 0 0 0 ${x} ${y+r}Z" fill="#88c1bf"/>`;
 if(model==='shadow_lamp'){const end=s.shadowEndX;b=`${line(35,210,485,210,'#899c85')}${sun(s.lampX,s.lampY,14)}${line(260,130,260,210,'#6a7f60',7)}${line(s.lampX,s.lampY,end,210,'#dfc571',2)}${line(260,213,end,213,'#566849',6)}${tx(200,247,'Fixed upright stick')}`;}
 if(model==='earth_rotation'||model==='earth_day_cycle'){const a=s.observerAngleDeg*Math.PI/180,px=285+60*Math.cos(a),py=130-60*Math.sin(a);b=`${sun(55,130,25)}${[90,130,170].map(y=>line(95,y,209,y)).join('')}${earth(285,130,70)}<circle cx="${px}" cy="${py}" r="7" fill="#ebc359"/>${tx(225,230,s.hours===undefined?'Marked observer':`${s.hours} hours from start`)}${tx(40,40,'Sunlight stays fixed')}`;}
 if(model==='day_record'){b=`${tx(55,45,'Example records · 示例记录')}${tx(60,90,`Shadow: ${s.shadowCm} cm`,20)}<rect x="60" y="105" width="${s.shadowCm*4}" height="25" rx="5" fill="#9ba990"/>${tx(60,180,`Temperature: ${s.tempC} °C`,20)}<rect x="60" y="195" width="${s.tempC*10}" height="20" rx="5" fill="#d4b774"/>${tx(60,250,'Different quantities — compare each row separately.',12)}`;}
 if(model==='seasons_tilt'){const xx=s.earthX,a=s.axisTiltDeg*Math.PI/180,dx=70*Math.sin(a),dy=70*Math.cos(a);b=`${sun(260,130,26)}<circle cx="${xx}" cy="130" r="48" fill="#8cbcc1"/>${line(xx-dx,130+dy,xx+dx,130-dy,'#48665c',3)}${tx(xx+dx+5,130-dy,'N')}${tx(xx-dx-17,130+dy,'S')}${line(xx<260?228:292,110,xx<260?174:346,110)}${line(xx<260?228:292,145,xx<260?174:346,145)}${tx(100,245,'Axis tilt stays in the same direction · 地轴方向不变')}`;}
 if(model==='daylight_hours'){b=`<rect x="40" y="90" width="432" height="60" rx="10" fill="#405b68"/><rect x="${40+s.sunrise*18}" y="90" width="${s.value*18}" height="60" fill="#e3bd62"/>${[0,6,12,18,24].map(h=>tx(33+h*18,177,String(h))).join('')}${tx(120,220,`${s.sunrise}:00 sunrise → ${s.sunset}:00 sunset`)}${tx(135,55,`${s.value} hours of daylight`,22)}`;}
 if(model==='moon_views'){const a=s.orbitAngleDeg*Math.PI/180,mx=190+85*Math.cos(a),my=125-85*Math.sin(a);b=`${sun(28,125,15)}<circle cx="190" cy="125" r="85" fill="none" stroke="#b7c4b5" stroke-dasharray="4 4"/>${earth(190,125,23)}${earth(mx,my,14)}${moonSymbol(413,125,48,s.litFraction,s.phaseName==='last-quarter')}${tx(93,245,'Orbit view · 轨道示意')}${tx(345,215,'View from Earth')}${tx(348,235,s.phaseName,12)}`;}
 if(model==='moon_prediction'){b=moonSymbol(260,120,75,s.litFraction)+tx(155,230,'Waxing Moon · 亮面逐渐增大');}
 if(model==='eclipse'){b=`${sun(55,130,27)}${earth(235,130,36)}<path d="M260 102L475 80V180L260 158Z" fill="#b0b6aa" opacity=".6"/><circle cx="400" cy="${s.moonY}" r="17" fill="${s.eclipsed?'#9b7a60':'#e9e0bb'}"/>${tx(315,220,s.eclipsed?'Moon in Earth shadow':'Moon above shadow')}${tx(48,245,'Alignment model, not to scale · 示意不按比例')}`;}
 if(model==='planet_motion'){const a=s.earthAngleDeg*Math.PI/180,z=s.marsAngleDeg*Math.PI/180;b=`<ellipse cx="260" cy="130" rx="90" ry="55" fill="none" stroke="#bccab6"/><ellipse cx="260" cy="130" rx="175" ry="100" fill="none" stroke="#bccab6"/>${sun(260,130,20)}<circle cx="${260+90*Math.cos(a)}" cy="${130-55*Math.sin(a)}" r="13" fill="#74aeb5"/><circle cx="${260+175*Math.cos(z)}" cy="${130-100*Math.sin(z)}" r="11" fill="#bd8b6a"/>${tx(85,250,'Time model: Earth 1 year; Mars about 2 years.',12)}`;}
 if(model==='space_rock'){const y=s.stage==='space'?55:s.stage==='atmosphere'?130:210;b=`<rect x="40" y="25" width="440" height="100" fill="#294854"/><rect x="40" y="125" width="440" height="85" fill="#b2d2da"/><rect x="40" y="210" width="440" height="30" fill="#a69978"/>${s.stage==='atmosphere'?'<path d="M190 65L260 130" stroke="#e5bd63" stroke-width="6"/>':''}<circle cx="260" cy="${y}" r="10" fill="#827963"/>${tx(65,200,'Atmosphere')}`;}
 if(model==='telescope_detail'){b=`<circle cx="260" cy="125" r="85" fill="#dedbbb"/>${Array.from({length:s.visibleCraters},(_,j)=>`<circle cx="${220+(j*37)%90}" cy="${70+(j*31)%110}" r="${8+j%3*3}" fill="none" stroke="#aeb29a" stroke-width="3"/>`).join('')}${tx(150,245,'Same object, more visible detail')}`;}
 if(model==='jupiter_moons'){b=`<rect x="35" y="25" width="450" height="190" rx="14" fill="#203e4d"/><circle cx="260" cy="120" r="25" fill="#cfb88a"/>${s.moonOffsets.map((v,j)=>`<circle cx="${260+v}" cy="120" r="5" fill="#eee2b7"/>`).join('')}${tx(120,245,'Compare positions around Jupiter')}`;}
 if(model==='sky_brightness'){let val=Math.round(25+s.backgroundBrightness*180);b=`<rect x="40" y="25" width="440" height="195" rx="12" fill="rgb(${val},${val+15},${val+24})"/>${Array.from({length:18},(_,j)=>`<circle cx="${70+(j*89)%380}" cy="${45+(j*41)%145}" r="2" fill="#dbe3d8"/>`).join('')}${tx(80,245,'Same stars; changing background brightness')}`;}
 if(model==='big_dipper'){let pts=[[100,90],[155,105],[210,130],[280,125],[325,90],[395,100],[380,155]];b=`<rect x="40" y="25" width="440" height="195" rx="12" fill="#264451"/>${s.showLines?`<polyline points="${pts.map(p=>p.join(',')).join(' ')} 280,125" fill="none" stroke="#a2bac0" stroke-width="2"/>`:''}${pts.map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="#f0e4b7"/>`).join('')}${tx(85,245,'Guide lines are imaginary · 连线不是太空实体')}`;}
 if(model==='night_view'){const xx=s.earthX,left=s.nightDirection==='left';b=`${sun(260,130)}<circle cx="${xx}" cy="130" r="32" fill="#7db0bc"/>${line(xx+(left?-35:35),130,left?30:490,130,'#7a9a89')}${tx(left?25:460,100,s.starGroup,22)}${tx(100,240,'The night side faces away from the Sun.')}`;}
 return b;}
